        "title_en": "The Century-Old Debate: Haas vs. Nowak Editions",
        "text": "布鲁克纳完成初稿（1887）后遭到指挥家列维（Hermann Levi）的无情拒绝，陷入重度抑郁。在弟子约瑟夫·沙尔克的协助下，布鲁克纳于1890年完成了大修版。学者罗伯特·哈斯（Robert Haas, 1939年版）敏锐地指出，1890年版中第三乐章与第四乐章展开部的部分删减并非布鲁克纳出于自愿，而是迫于沙尔克的催促与外部压力，哈斯版审慎恢复了这些神来之笔。君特·旺德、卡拉扬、切利比达克等大师终生坚定支持哈斯版，认为其结构最具恢弘完整的建筑美感。",
        "text_en": "After conductor Hermann Levi rejected the 1887 premiere score, a devastated Bruckner thoroughly revised the symphony in 1890 with Josef Schalk. Musicologist Robert Haas (1939) restored several tragic cuts made under pressure in the Adagio and Finale development. Günter Wand, Herbert von Karajan, and Sergiu Celibidache champion the Haas edition for its monumental architectural proportions."
