              "title": "列维拒绝总谱的导火索：崩溃的高潮",
              "title_en": "The Climax that Stunned Levi",
              "shortTitle": "灾变高潮",
              "shortTitle_en": "Cataclysmic Summit",
              "body": "1887年初稿寄给指挥家赫尔曼·列维时，列维被这段近乎残酷的末日崩溃彻底吓退，认为其‘不可演奏且野蛮失控’。布鲁克纳在1890年的大修中并未削弱这里的毁灭力度，而是强化了其复调逻辑：三连音不是宣泄，而是命运战车无情碾过的车辙声！",
              "body_en": "When conductor Hermann Levi received the 1887 score, he was terrified by this brutal, uncompromising catastrophe. Bruckner kept the cataclysm intact in 1890, tightening its contrapuntal architecture.",
              "listen": "在原声中感受君特·旺德如何用外科手术般的严密节奏控制铜管爆棚，不留一丝浑浊泥浆。",
              "listen_en": "Listen to Wand's surgical precision maintaining crystal voice transparency even at fff.",
