          "desc": "定音鼓与低音弦乐在C小调中砸下沉重而质朴的三拍子重音，第一小提琴以飞掠的十六分音符三连音涡流扶摇直上，展现出奥地利民俗中‘德意志米歇尔’朴实无华但力拔山兮的蛮劲。",
