              "shortTitle": "德意志米歇尔",
              "shortTitle_en": "German Michel",
              "body": "布鲁克纳曾亲笔写信给列维解释这个乐章的主角：‘这就是德意志米歇尔——那个戴着尖顶睡帽、老实巴交但骨子里力大无穷的乡下汉子。他醒来伸个懒腰，然后在泥土里跳起笨拙而快乐的民间兰德勒舞！’旺德的指挥让这里的节奏极其方正硬朗，毫无维也纳沙龙的轻佻浮华，全是阿尔卑斯巨石的厚重质感。",
              "body_en": "Bruckner explained to Levi: 'This is the German Michel, the naive, honest folk giant who awakens and stamps his boots upon the earth!'",
