          "desc": "西方音乐史上最伟大的复调奇迹登峰造极！在灿烂无匹的C大调主和弦中，布鲁克纳完成了人类智慧的神迹：小号吹响第一乐章2+3命运动机，圆号吹响第二乐章米歇尔踏足主题，长号吹响第三乐章慢板天国圣咏，低音大号与大提琴吹响第四乐章骑兵号角！四个完全独立的乐章主题在不同乐器里同时并置轰鸣，纵向和声纯净协和，横向旋律各自奔腾！",
          "desc_en": "The absolute summit of western counterpoint! All four movement themes sound simultaneously across the orchestra in triumphant C major: Trumpets (Mvt 1), Horns (Mvt 2), Trombones (Mvt 3), and Bass Tubas (Mvt 4)!",
          "foreground": "小号(乐章1 2+3) + 圆号(乐章2 米歇尔) + 长号(乐章3 慢板) + 低音(乐章4 骑兵)四重对位同时轰鸣！",
          "foreground_en": "Trumpets (M1) + Horns (M2) + Trombones (M3) + Tubas (M4) in Quadruple Counterpoint!",
          "background": "全弦乐金光狂澜与定音鼓雷霆万钧的重锤基石",
          "background_en": "Full strings golden waves and thunderous timpani",
          "focus": "在钢琴卷帘中点击各个声部单独静音或独奏，验证西方复调史最高神迹的严丝合缝！",
          "focus_en": "Mute/solo each track in the piano roll to inspect all 4 themes coexisting in vertical harmony!",
